import{_ as r,o as t,c as i,j as a,a as e,a5 as o}from"./chunks/framework.R-FQ1xZ2.js";const m=JSON.parse('{"title":"双路召回、RRF 融合与精排","description":"稠密路与稀疏路各自召回，怎么融合、怎么精排、最后怎么拼上下文。","frontmatter":{"title":"双路召回、RRF 融合与精排","description":"稠密路与稀疏路各自召回，怎么融合、怎么精排、最后怎么拼上下文。"},"headers":[],"relativePath":"diagrams/rag-dual-retrieval.md","filePath":"diagrams/rag-dual-retrieval.md","lastUpdated":null}'),s={name:"diagrams/rag-dual-retrieval.md"};function n(d,l,c,h,f,u){return t(),i("div",null,[...l[0]||(l[0]=[a("h1",{id:"双路召回、rrf-融合与精排",tabindex:"-1"},[e("双路召回、RRF 融合与精排 "),a("a",{class:"header-anchor",href:"#双路召回、rrf-融合与精排","aria-label":'Permalink to "双路召回、RRF 融合与精排"'},"​")],-1),a("p",null,[a("span",{class:"fig-badge"},"数据流图"),e(),a("code",null,"dataflow")],-1),a("blockquote",null,[a("p",null,[a("strong",null,"一句话"),e("：稠密路与稀疏路各自召回，怎么融合、怎么精排、最后怎么拼上下文。")])],-1),a("div",{class:"fig-frame"},[a("iframe",{src:"/fig/rag-dual-retrieval.html",title:"双路召回、RRF 融合与精排",loading:"lazy",allowfullscreen:""})],-1),o('<p class="fig-actions"><a href="/fig/rag-dual-retrieval.html" target="_blank" rel="noreferrer">在新窗口打开（可缩放 / 切换明暗主题 / 导出图片）</a></p><h2 id="怎么读这张图" tabindex="-1">怎么读这张图 <a class="header-anchor" href="#怎么读这张图" aria-label="Permalink to &quot;怎么读这张图&quot;">​</a></h2><ol><li>两条召回路径是并行的，各自取 top-20；融合用 RRF 而不是分数加权，原因是两路分数量纲根本不可比。</li><li>融合后用交叉编码器精排，精排的输出 top-1 分数同时承担第二个职责——它是拒答判据的来源。</li><li>最后一步是上下文组装：不是把 top-k 全塞进去，而是受 token 预算约束，塞不下要按分数截断，被截断的部分要留痕迹。</li><li>看图上标注的 top_k 数值：召回是 20，精排后进上下文的是 5，这两个数不要混。</li></ol><h2 id="面试口径" tabindex="-1">面试口径 <a class="header-anchor" href="#面试口径" aria-label="Permalink to &quot;面试口径&quot;">​</a></h2><ul><li>「混合检索一定比纯向量好吗？」——不一定，这个项目里就有反例：扩库后混合检索 R@5 从 64.5% 崩到 29.2%，所以要能说出什么时候不该混。</li><li>「RRF 的 k 取多少？」——60，而且要知道它为什么是这个量级：它控制的是排名差异被压平的程度。</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/learn/projects/rag/04-retrieval.html">检索层</a></li><li><a href="/learn/projects/rag/05-rerank.html">重排与上下文组装</a></li><li><a href="/learn/diagrams/rag-sparse-selfcheck.html">稀疏路自检失效</a></li></ul>',7)])])}const g=r(s,[["render",n]]);export{m as __pageData,g as default};
